CREATE TABLE BILLING.BILL_LINE_ITEM
(
 BILL_LINE_ITEM_ID  varchar(30) NOT NULL COMMENT 'Primary key for bill line item.',
 ADDRESS            string NOT NULL,
 BILL_ID            varchar(30) NOT NULL COMMENT 'Foreign key to Bill.',
