 CHARGE_TYPE_ID     int NOT NULL COMMENT 'Foreign key to Charge Type.',
 CHARGE_DESCRIPTION varchar(200) COMMENT 'Description of the charge.',
 QUANTITY           decimal(12,3) COMMENT 'Quantity of service consumed or units billed.',
 UNIT_OF_MEASURE    varchar(20) COMMENT 'Unit of measurement (e.g., Cubic Meters).',
 UNIT_PRICE         decimal(12,2) COMMENT 'Price per unit.',
